package com.example.lrb.service.impl;
import com.example.lrb.service.UploadService; import com.example.lrb.utils.OssUtils; import com.example.lrb.vo.JsonResult; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.UUID;
@Service public class UploadServiceImpl implements UploadService { private final OssUtils oss; public UploadServiceImpl(OssUtils oss){this.oss=oss;} private JsonResult<String> upload(MultipartFile f,String dir)throws IOException{if(f==null||f.isEmpty())return JsonResult.badRequest("文件不能为空");String n=f.getOriginalFilename();String suffix=n!=null&&n.lastIndexOf('.')>=0?n.substring(n.lastIndexOf('.')):"";String url=oss.uploadFile(dir+"/"+UUID.randomUUID()+suffix,f.getInputStream());return url==null?JsonResult.interServerError("上传失败"):JsonResult.ok(url);} public JsonResult<String> uploadImage(MultipartFile f)throws IOException{return upload(f,"image");}public JsonResult<String> uploadVideo(MultipartFile f)throws IOException{return upload(f,"video");}}
